#!/usr/bin/env python3
"""Build the static RV Litigation site. Python standard library only.
Edit practice copy below and retained content/ fragments, then run this script.
Migration sources are explicit in content/legacy-paths.json; no server config required.
"""
from pathlib import Path
from html import escape as e
from urllib.parse import urlsplit
import json
ROOT=Path(__file__).resolve().parents[1]
BASE='https://rvlitigation.com'
DATE='2026-10-05'
PAGES={}
NAV=[('/business-litigation/','Business Litigation'),('/business-transactions/','Business Transactions'),('/tax-law/','Tax Law'),('/white-collar-defense/','White-Collar Defense'),('/professionals','Attorneys'),('/contact','Contact')]
SECONDARY=[('/about','About'),('/reviews','Reviews'),('/resources/','Resources'),('/locations/','Areas We Serve'),('/criminal-defense/','Selected Criminal Defense'),('/small-claims/','Small Claims')]
def links(items):
 return ''.join(f'<a href="{u}">{e(t)}</a>' for u,t in items)
def header():
 return f'''<a class="rv-skip" href="#main">Skip to content</a><header class="rv-header"><div class="rv-nav"><a class="rv-logo" href="/" aria-label="RV Litigation Group PC home"><img src="/images/Logos/RV_logo_long.png" width="242" height="40" alt="RV Litigation Group PC"></a><button class="rv-menu-toggle" type="button" aria-controls="site-menu" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button><nav id="site-menu" class="rv-menu" aria-label="Main navigation">{links(NAV)}<a class="rv-nav-call" href="tel:+14157977591">(415) 797-7591</a></nav></div></header>'''
def footer():
 return f'''<footer class="rv-footer"><div class="rv-container rv-footer-grid"><div><img src="/images/Logos/RV_logo_long.png" width="242" height="40" alt="RV Litigation Group PC"><p>Strategic counsel for businesses<br>and the people behind them.</p><address>28 Geary St, Suite 650<br>San Francisco, CA 94108</address><p><a href="tel:+14157977591">(415) 797-7591</a><br><a href="mailto:David@RVLitigation.com">David@RVLitigation.com</a></p></div><nav aria-label="Practice areas"><h2>Practice Areas</h2>{links(NAV[:4])}</nav><nav aria-label="Additional navigation"><h2>The Firm</h2>{links(SECONDARY)}<a href="/faq/">Frequently Asked Questions</a><a href="https://www.instagram.com/rv_litigation/">Instagram</a></nav></div><div class="rv-container rv-fineprint"><p>Attorney advertising. This website provides general information, not legal advice. Prior results do not guarantee a similar outcome. Contacting the firm does not create an attorney-client relationship. Do not send confidential information until we have agreed to represent you.</p><p>© 2026 RV Litigation Group PC. All rights reserved. <a href="/privacy-policy">Privacy Policy</a></p></div></footer>'''
def path_for(url):
 return ROOT/('index.html' if url=='/' else url.strip('/')+'/index.html' if url.endswith('/') else url.strip('/')+'.html')
def write(url,title,description,body,noindex=False):
 canonical=BASE+url
 if '<h1' not in body:body=body.replace('<h2>', '<h1>', 1).replace('</h2>', '</h1>', 1)
 schema={'@context':'https://schema.org','@graph':[{'@type':'LegalService','@id':BASE+'/#firm','name':'RV Litigation Group PC','url':BASE+'/','telephone':'+1-415-797-7591','email':'David@RVLitigation.com','image':BASE+'/images/Logos/RV_logo_center.png','address':{'@type':'PostalAddress','streetAddress':'28 Geary St, Suite 650','addressLocality':'San Francisco','addressRegion':'CA','postalCode':'94108','addressCountry':'US'},'areaServed':{'@type':'State','name':'California'}},{'@type':'WebPage','@id':canonical+'#webpage','url':canonical,'name':title,'description':description,'about':{'@id':BASE+'/#firm'}}]}
 full=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)} | RV Litigation Group PC</title><meta name="description" content="{e(description,quote=True)}"><meta name="robots" content="{'noindex, follow' if noindex else 'index, follow'}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:site_name" content="RV Litigation Group PC"><meta property="og:url" content="{canonical}"><meta property="og:title" content="{e(title,quote=True)} | RV Litigation Group PC"><meta property="og:description" content="{e(description,quote=True)}"><meta property="og:image" content="{BASE}/images/Logos/RV_logo_center.png"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title,quote=True)}"><meta name="twitter:description" content="{e(description,quote=True)}"><meta name="twitter:image" content="{BASE}/images/Logos/RV_logo_center.png"><link rel="icon" type="image/png" sizes="192x192" href="/images/Favicon/android-chrome-192x192.png"><link rel="apple-touch-icon" href="/images/Favicon/apple-touch-icon.png"><link rel="manifest" href="/images/Favicon/site.webmanifest"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@400;500;600&family=Montserrat:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/css/styles.css"><link rel="stylesheet" href="/css/rebuild.css"><script type="application/ld+json">{json.dumps(schema)}</script><script src="/js/main.js" defer></script></head><body>{header()}<main id="main">{body}</main>{footer()}</body></html>'''
 p=path_for(url);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(full)
 PAGES[url]={'title':title,'index':not noindex}
def section(title,body,tag='',light=False):
 return f'<section class="rv-section{" rv-light" if light else ""}"><div class="rv-container">'+(f'<p class="rv-eyebrow">{e(tag)}</p>' if tag else '')+f'<h2>{e(title)}</h2>{body}</div></section>'
def intro(title,text,tag='RV Litigation Group PC',parent=None):
 crumbs='<a href="/">Home</a>'+(f' <span aria-hidden="true">/</span> <a href="{parent[0]}">{e(parent[1])}</a>' if parent else '')
 return f'<section class="rv-page-intro"><div class="rv-container"><nav class="rv-breadcrumb" aria-label="Breadcrumb">{crumbs}</nav><p class="rv-eyebrow">{e(tag)}</p><h1>{e(title)}</h1><p class="rv-lead">{e(text)}</p><a class="rv-button" href="/contact">Request a Consultation <span aria-hidden="true">↗</span></a></div></section>'
def paras(*texts):return ''.join(f'<p>{e(t)}</p>' for t in texts)
def bullets(items):return '<ul class="rv-list">'+''.join('<li>'+e(t)+'</li>' for t in items)+'</ul>'
def cards(items):
 return '<div class="rv-cards">'+''.join(f'<a class="rv-card" href="{u}"><span class="rv-card-number">{i:02}</span><h3>{e(t)}</h3><p>{e(d)}</p><span class="rv-card-link">Explore <span aria-hidden="true">↗</span></span></a>' for i,(u,t,d) in enumerate(items,1))+'</div>'
def faq(items):
 return section('Questions & Answers','<div class="rv-faq">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in items)+'</div>','Before we begin')
def cta(title='Let’s discuss your next step.',text='Tell us what is happening, who is involved, and whether a deadline is approaching. We will review whether the matter fits our practice.'):
 return section(title,paras(text)+'<div class="rv-actions"><a class="rv-button" href="/contact">Request a Consultation ↗</a><a class="rv-text-link" href="tel:+14157977591">(415) 797-7591</a></div>','Start a conversation',True)
GROUPS={
'business-litigation':{'title':'Business Litigation','intro':'Focused representation for businesses, owners, and executives facing commercial disputes. We evaluate the business objective, build the record, and prepare for negotiation or court.','services':['Contract and payment disputes','Partnership, ownership, and fiduciary-duty disputes','Trade secrets, business fraud, and unfair competition','Commercial leases and real estate disputes','Employer-side workplace litigation','Urgent court relief and ongoing litigation counsel'],'situations':'A key agreement has broken down. An owner is blocking decisions or diverting business. A demand letter or lawsuit threatens operations. We help assess the legal position and the practical consequences together, including cost, timing, evidence, and the ongoing commercial relationship.','approach':'We begin with the contracts, communications, deadlines, and business objectives. From there, we develop a plan for preserving evidence, evaluating claims and defenses, and pursuing an appropriate resolution. Negotiation and litigation preparation can proceed together; the right path depends on the facts and the client’s goals.','attorney':'David Ruezga','faq':[('Do you represent businesses bringing and defending claims?','Yes. We evaluate both claims a business may pursue and allegations made against a business or its owners.'),('Do you represent employees in workplace claims?','No. Our employment practice represents businesses and employers. We do not take employee-side employment matters.'),('How are litigation fees handled?','Our business litigation work is handled on a retainer basis, not a contingency basis. Scope and fee terms are discussed before an engagement is accepted.')]},
'business-transactions':{'title':'Business Transactions','intro':'Practical legal support for the agreements and decisions that shape a business. We help owners put clear terms in place before a deal, ownership change, or commercial relationship moves forward.','services':['Business contract drafting, review, and negotiation','Ownership and operating agreements','Business purchases and sales','Coordination of transaction and dispute considerations'],'situations':'You are signing a significant customer or vendor agreement, bringing a new owner into the company, or negotiating a purchase or sale. We help identify the decisions that should be made before signing, including responsibilities, payment, control, and what happens if the relationship changes.','approach':'We learn how the business operates and what the transaction needs to accomplish. We review proposed terms, flag unresolved obligations, and work through negotiation and documentation. When tax or dispute questions overlap, we coordinate the legal work so those issues are considered together.','attorney':'Matthew Williams','faq':[('Can you review an agreement before I sign it?','Yes. Share a brief description of the agreement and any signing deadline when you contact us. We will confirm the scope and availability before accepting the work.'),('Can you work with my accountant or other advisers?','Yes. With your authorization, we can coordinate legal questions with your other advisers and clarify who is responsible for each part of the transaction.'),('Can you help after a business relationship breaks down?','Our Business Litigation practice evaluates disputes. We can help determine whether the immediate need is a revised agreement, negotiation, or litigation.')]},
'tax-law':{'title':'Tax Law','intro':'Tax counsel for individuals, businesses, and the people responsible for business decisions. We help address federal and California tax disputes, audits, appeals, and matters that raise enforcement concerns.','services':['IRS audits and administrative appeals','California tax disputes','Business tax matters','Tax litigation and appeals','Criminal tax defense in coordination with white-collar counsel'],'situations':'A tax notice arrives, an audit expands, or an unresolved disagreement moves toward an appeal. Owners may also need to understand how a tax issue affects the business and their own position. We help identify the stage of the matter, the information needed, and the legal response to consider.','approach':'We start with the notice, the agency involved, the tax periods, and the response dates. We assess the available record and work with you and, when authorized, your accounting advisers. If the matter involves potential criminal exposure, we coordinate tax and defense strategy before a response is made.','attorney':'Matthew Williams','faq':[('Do you handle individual and business tax matters?','Yes. Tax Law covers both individuals and businesses. Our Business Tax page addresses matters involving a company and its owners.'),('Should I send tax returns through the contact form?','No. Start with a brief description, the agency involved, and the deadline. We will provide instructions for sharing documents if the matter proceeds.'),('Is tax return preparation offered here?','These pages describe legal representation in tax matters. Please explain your needs so we can confirm whether they fit the firm’s legal services.')]},
'white-collar-defense':{'title':'White-Collar Defense','intro':'Strategic defense for individuals, executives, and businesses facing investigations or financial-crime allegations. We address the legal exposure and the consequences for the person and the business.','services':['Investigations, subpoenas, and requests for interviews','Financial fraud allegations','Embezzlement allegations','Criminal tax matters with coordinated tax counsel'],'situations':'An investigator requests an interview, a subpoena seeks company records, or questions arise about transactions and financial controls. Representation can begin before a charge is filed. We assess whose interests are involved and whether the company and an individual need separate counsel.','approach':'We clarify the status of the investigation, identify immediate obligations, and develop a response based on the records and allegations. Preparation may include reviewing transactions, preserving relevant information, communicating with investigators through counsel, and evaluating a negotiated resolution or defense in court.','attorney':'David Ruezga','faq':[('Can I contact you before charges are filed?','Yes. We review matters at the investigation stage as well as after charges are filed. Include any interview, subpoena, or court deadline in your initial inquiry.'),('Can one lawyer represent the business and an executive?','That depends on the circumstances and potential conflicts. We review representation separately before agreeing to act for a company or an individual.'),('Do you still handle other criminal matters?','Selected criminal defense matters remain available through our secondary practice page. Contact us to confirm whether we can consider your matter.')]}}
# Each detail page has matter-specific substance; common process stays on the parent hub.
DETAILS=[
('business-litigation','business-fraud','Business Fraud Disputes','Representation for businesses in disputes involving alleged misrepresentations, concealed information, and fraudulent commercial conduct. We evaluate claims and defenses in the context of the transaction.',['Alleged misrepresentations in business agreements','Disputed disclosures and transaction information','Related contract and business tort claims','Defense of business fraud allegations'],'A business believes it entered a transaction based on misleading information, or an owner faces allegations about what was said or disclosed. The claim requires a careful examination of the communications, the agreement, and the loss alleged.','We review the representations at issue, the available documents, and the business decisions that followed. We distinguish the disputed facts from assumptions and assess potential claims, defenses, and the practical objective of negotiation or litigation.'),
('business-litigation','contract-disputes','Contract Disputes','When performance, payment, or contract terms are contested, the business needs a clear assessment of its options. We represent businesses in disputes over commercial agreements.',['Breach of written business agreements','Disputed payment, delivery, or performance','Termination and interpretation disagreements','Negotiation, settlement, and litigation'],'A customer withholds payment, a supplier stops performing, or the parties disagree about what a contract requires. The written terms are the starting point, but amendments, communications, and the parties’ conduct can also matter.','We review the agreement and the events leading to the dispute, identify the available evidence, and assess the commercial objective. A demand, negotiated adjustment, settlement, or lawsuit may serve different goals. We discuss those choices with the business before committing to a course of action.'),
('business-litigation','partnership-disputes','Partnership & Ownership Disputes','Disagreements among owners can disrupt decisions, access to information, and the future of a business. We help business owners address disputes with a plan grounded in the governing agreements.',['Owner and partner disagreements','Management and voting disputes','Access to business records','Buyout, exit, and dissolution-related disputes'],'An owner wants to leave, decisions have stalled, or one partner questions the use of business funds. These disputes often involve both a legal claim and an ongoing operational problem.','We review ownership and operating agreements, relevant records, and the business’s decision-making structure. We assess negotiation and litigation options while considering whether the objective is continued operation, a negotiated separation, or another resolution.'),
('business-litigation','breach-of-fiduciary-duty','Breach of Fiduciary Duty','We represent businesses and owners in disputes involving alleged misuse of authority, conflicts of interest, and obligations arising from trusted business relationships.',['Alleged diversion of company funds or opportunities','Conflicts involving officers, managers, or partners','Disclosure and accounting disagreements','Defense of fiduciary-duty allegations'],'A manager enters a transaction benefiting another company, an owner questions payments, or a departing partner is accused of taking a business opportunity. The relationship and the specific conduct determine which duties may be at issue.','We analyze the governing documents, the roles of the people involved, and the transaction history. Our approach connects the alleged conduct to the evidence, the available defenses, and the practical remedy the client needs.'),
('business-litigation','trade-secret-litigation','Trade Secret Litigation','Confidential business information can be central to a company’s operations. We help businesses evaluate claims involving alleged misuse or disclosure and respond to allegations against them.',['Disputes involving confidential business information','Employee or business-partner departures','Alleged misuse of customer or technical information','Urgent relief and litigation strategy'],'A departing worker has access to sensitive records, a competitor begins using disputed information, or your business receives a demand accusing it of misappropriation. Early decisions about information and evidence can affect the dispute.','We review the information at issue, the measures used to protect it, and how access or disclosure occurred. We coordinate the factual record with the company’s operational needs and evaluate negotiated protections, court relief, and defenses.'),
('business-litigation','commercial-lease-disputes','Commercial Lease Disputes','Representation for businesses and commercial property interests in disputes over leased premises. Our focus is commercial leases, not residential landlord-tenant matters.',['Commercial rent and payment disputes','Lease interpretation and performance','Maintenance, use, and improvement obligations','Commercial lease termination and exit disputes'],'A location is essential to operations, but the parties disagree about payment, repairs, permitted use, or an exit. The legal strategy should account for both the lease and the business’s ability to operate.','We review the lease, amendments, notices, and the record of performance. We assess the disputed obligations and work toward a resolution that considers business continuity, potential exposure, and the cost of litigation.'),
('business-litigation','commercial-real-estate-disputes','Commercial Real Estate Disputes','We help businesses address disputes involving commercial property agreements and transactions. This practice is focused on business property matters.',['Commercial property purchase and sale disputes','Disputed contractual obligations','Business-related ownership disagreements','Negotiated resolution and litigation'],'A commercial property transaction stalls, a party disputes a contractual obligation, or business owners disagree about a property investment. We evaluate how the documents and facts support the requested outcome.','We review the transaction documents, communications, and the interests at stake. Our work focuses on understanding the disputed obligations and developing a practical path through negotiation or litigation. Residential and neighborhood disputes are outside this practice.'),
('business-litigation','unfair-business-practices','Unfair Business Practices','We help businesses evaluate and respond to allegations involving unfair competition and disputed commercial conduct.',['Business-to-business competition disputes','Allegations about commercial representations','Related contract and business tort claims','Defense and negotiated resolution'],'A competitor’s conduct threatens a business relationship, or your company faces allegations about its own practices. The key questions include the challenged conduct, the parties affected, and the evidence supporting the claim.','We analyze the conduct and its commercial context, assess the potential claims and defenses, and identify the relief that may be available. Our strategy accounts for the business’s operations and reputation as well as the dispute itself.'),
('business-litigation','employment-workplace-litigation','Employer-Side Workplace Litigation','We represent businesses and employers in workplace disputes. We do not represent employees pursuing claims against employers.',['Defense of workplace-related claims against employers','Disputes involving employment agreements','Confidentiality and business-information disputes','Employer-focused negotiation and litigation'],'An employer receives a demand or lawsuit, a workplace dispute escalates, or a departure raises questions about contractual obligations and company information. Contact us with the business’s role and any immediate deadline.','We review the allegations, relevant policies and agreements, and the employment records needed to assess the matter. We work with the business to evaluate exposure and response options. Acceptance depends on the specific claims and the scope of representation; no category of matter is automatically accepted.'),
('business-litigation','urgent-injunctions-tros','Urgent Injunctions & TROs','Some business disputes require an assessment of urgent court relief. We evaluate requests for temporary restraining orders and injunctions in commercial matters.',['Threatened disclosure of business information','Disputed transfers or control of business assets','Conduct threatening ongoing operations','Response to requests for urgent court orders'],'A business believes a threatened action cannot be adequately addressed later, or it has been served with an emergency application. The available time, evidence, and requested order need immediate attention.','We assess the factual support, procedural requirements, and practical effects of the proposed relief. Contact us by phone if a hearing or deadline is imminent. An online inquiry does not confirm that we have accepted the matter or can meet a particular deadline.'),
('business-litigation','outside-litigation-counsel','Outside Litigation Counsel','Ongoing litigation counsel for businesses that need a consistent legal point of contact as disputes develop.',['Assessment of demands and emerging disputes','Coordination of litigation strategy','Review of dispute-related communications','Management of active litigation within an agreed scope'],'The business has recurring disputes, several matters to coordinate, or a developing problem that requires counsel before it becomes a lawsuit. An ongoing relationship can help keep decisions aligned with the company’s goals.','We define the scope of work and communication expectations at the outset. We then help evaluate priorities, monitor agreed matters, and coordinate strategy with the business’s leadership and other advisers. Engagement and retainer terms are documented before work begins.'),
('business-transactions','business-contracts','Business Contracts','Clear agreements help a business define expectations before commitments are made. We draft, review, and negotiate commercial contracts.',['Customer and service agreements','Vendor and commercial relationship agreements','Contract amendments and renewals','Termination and dispute-resolution terms'],'You are entering a new relationship or updating terms that no longer fit how the business works. We help identify obligations, risk allocation, and practical issues that deserve attention before signature.','We begin with the commercial objective and the proposed terms. We review performance, payment, duration, termination, and dispute provisions in context, then help the business negotiate and document its decisions.'),
('business-transactions','ownership-agreements','Ownership Agreements','We help owners document how a business will be managed and how changes in ownership will be handled.',['Operating and partnership agreements','Owner roles and decision-making provisions','Buyout and transfer arrangements','Amendments for changing ownership needs'],'New owners are joining, responsibilities have changed, or the business needs clearer rules for decisions and departures. An agreement should reflect how the owners intend to work together.','We identify the ownership structure, management expectations, and unresolved points. We help document control, contributions, transfers, and exit arrangements, while coordinating related tax or dispute questions when appropriate.'),
('business-transactions','business-purchases-sales','Business Purchases & Sales','Legal support for buyers and sellers working through the terms of a business transaction.',['Review of proposed deal terms','Purchase and sale agreements','Transaction-document negotiation','Coordination of legal diligence and closing obligations'],'A buyer or seller needs to move from an initial understanding to enforceable documents. We help identify what is included in the deal, what obligations remain, and which questions must be resolved before closing.','We review the proposed structure, contracts, and the issues identified during diligence. We work through representations, payment provisions, closing conditions, and related documents within the agreed engagement. Tax and accounting advisers can be included with the client’s authorization.'),
('tax-law','business-tax','Business Tax','Tax disputes can affect both a company and the people who own or manage it. We help businesses address legal questions arising from tax notices, examinations, and contested positions.',['Business tax notices and examinations','Disputed assessments and administrative appeals','Coordination with accounting advisers','Owner and business interests in overlapping tax matters'],'A business receives an agency notice, records are requested, or owners are concerned about how a company tax issue affects them personally. Identifying the taxpayer, agency, and tax periods helps define the matter.','We assess the notice and procedural stage, review the relevant record, and help develop a legal response. We coordinate with authorized advisers and assess any potential conflicts between a company and its owners before agreeing to representation.'),
('tax-law','irs-audits-appeals','IRS Audits & Appeals','Legal representation for individuals and businesses addressing IRS examinations and administrative appeals.',['Audit notices and information requests','Evaluation of disputed federal tax positions','Administrative appeal preparation','Coordination of supporting records'],'You have received an IRS notice, an examiner has requested information, or you disagree with a proposed adjustment. The first step is to understand what the agency is asking and which response dates apply.','We review the correspondence and supporting records, assess the disputed issues, and help prepare an organized response or appeal. Where appropriate, we coordinate with your accountant to separate factual and accounting questions from legal advocacy.'),
('tax-law','california-tax-disputes','California Tax Disputes','Counsel for individuals and businesses facing disputes with California tax authorities.',['State tax notices and disputed assessments','Agency correspondence and examinations','Administrative dispute and appeal strategy','Coordination of state and federal tax issues'],'A California tax notice may involve a different agency, record, or timeline from a related federal matter. Tell us which agency contacted you, what the notice concerns, and when a response is due.','We identify the applicable process, assess the agency’s position, and review the record supporting the taxpayer’s response. Scope is confirmed for the particular agency and issue; we do not assume every state tax matter follows the same procedure.'),
('tax-law','tax-litigation-appeals','Tax Litigation & Appeals','Representation in contested tax matters that require a formal appeal or court proceeding.',['Assessment of the dispute and procedural posture','Preparation of the factual and legal record','Tax litigation strategy','Resolution discussions and appeals within the agreed scope'],'A dispute has moved beyond an initial inquiry or proposed adjustment. The available forum and next procedural step depend on the type of tax, the notice received, and the history of the matter.','We review the case record, identify deadlines and jurisdictional questions, and assess the legal arguments. Matthew Williams’s existing admissions include the U.S. Tax Court. We confirm the appropriate forum and scope of representation for each engagement.'),
('tax-law','criminal-tax-defense','Criminal Tax Defense','Coordinated tax and white-collar defense when a tax matter involves allegations of criminal conduct or an investigation.',['Tax-related investigations','Interview and records requests','Allegations involving reporting or tax-related conduct','Coordination of tax and defense strategy'],'An investigator contacts you, a routine tax issue appears to have escalated, or a business and an owner have different concerns. Tax procedure and criminal exposure require coordinated attention.','We clarify the status of the matter, assess potential conflicts, and coordinate tax analysis with defense counsel. The legal strategy considers both the tax record and the allegations under investigation.'),
('white-collar-defense','investigations-subpoenas','Investigations & Subpoenas','Counsel for businesses and individuals responding to investigations, subpoenas, and requests for information.',['Subpoenas for documents or testimony','Requests for interviews','Investigation-stage representation','Coordination of company and individual interests'],'A request for records or an interview can arrive before anyone knows the full scope of an investigation. A business may need to preserve information while considering the interests of employees and leadership.','We review the request, the response date, and the records involved. We assess the representation needed and develop an organized response, including appropriate communications through counsel and consideration of separate representation where interests differ.'),
('white-collar-defense','financial-fraud','Financial Fraud Defense','Defense of individuals and businesses facing allegations of fraudulent financial conduct.',['Alleged misrepresentations in financial transactions','Business and financial records review','Investigation-stage strategy','Negotiation and defense of filed charges'],'Transactions that appear straightforward in isolation may be disputed when examined across records, communications, and the roles of different participants. We focus on the specific allegations and what the evidence shows.','We analyze the transactions, relevant communications, and the client’s role. We evaluate the prosecution’s theory and available defenses, while considering related business disputes and tax issues that may require coordinated attention.'),
('white-collar-defense','embezzlement','Embezzlement Defense','Representation for people accused of misusing money or property entrusted to them in a business or professional relationship.',['Disputed use of business funds','Accounting and authorization questions','Workplace-related financial allegations','Investigations and defense of charges'],'A payment, transfer, reimbursement, or use of an account may be challenged after a workplace or ownership relationship breaks down. The records and the scope of authority can be important to understanding the allegation.','We review financial records, approvals, communications, and the circumstances of the transactions. We develop a defense based on the actual evidence and consider related employment or ownership disputes without assuming they resolve the criminal allegation.')]

def attorney(name):
 return section('Counsel for your matter',f'<div class="rv-attorney-note"><h3>{e(name)}</h3><p>'+('Tax and business counsel, with existing admissions including the U.S. Tax Court. Matthew’s litigation background informs the assessment of disputes and transactions.' if name=='Matthew Williams' else 'Founder and president of RV Litigation Group PC. David works with the firm’s legal team to develop the strategy and scope appropriate to each engagement.')+'</p><a class="rv-text-link" href="/professionals">Meet our attorneys ↗</a></div>')

def make_practices():
 for slug,g in GROUPS.items():
  children=[('/'+s+'/'+child+'/',t,desc) for s,child,t,desc,*_ in DETAILS if s==slug]
  if slug=='white-collar-defense':children.append(('/tax-law/criminal-tax-defense/','Criminal Tax Defense','Coordinated tax and white-collar counsel for tax-related investigations.'))
  b=intro(g['title'],g['intro'],'California legal counsel')
  b+=section('How we can help',bullets(g['services'])+cards(children),'Practice focus',True)
  b+=section('When to involve counsel',paras(g['situations']))+section('Our approach',paras(g['approach']))+attorney(g['attorney'])+faq(g['faq'])
  b+=section('Related practices',cards([('/'+s+'/',v['title'],v['intro']) for s,v in GROUPS.items() if s!=slug]))+cta()
  write('/'+slug+'/',g['title']+' Attorneys in California',g['intro'],b)
 for group,slug,title,desc,services,situation,approach in DETAILS:
  g=GROUPS[group]
  questions=[('What should I include in an initial inquiry?','Briefly describe the issue, the people or businesses involved, and any known deadline. Please do not send confidential records or detailed financial information through the contact form.'),('Will the firm accept every matter in this area?','No. We first review the fit, conflicts, scope, and availability. Representation begins only after the firm agrees to an engagement.'),('How will I know the scope and fees?','We discuss the proposed work and fee terms before accepting an engagement. The scope depends on the particular matter and its procedural stage.')]
  if slug=='employment-workplace-litigation':questions[0]=('Do you represent employees?','No. This service is exclusively for businesses and employers, not employees bringing claims.')
  b=intro(title,desc,g['title'],('/'+group+'/',g['title']))+section('Matters we handle',bullets(services),'Scope of representation',True)+section('Situations we review',paras(situation))+section('How we approach the matter',paras(approach))+attorney(g['attorney'])+faq(questions)
  related=[('/'+s+'/'+child+'/',t,d) for s,child,t,d,*_ in DETAILS if s==group and child!=slug][:3]
  if slug=='criminal-tax-defense':related.insert(0,('/white-collar-defense/','White-Collar Defense',GROUPS['white-collar-defense']['intro']))
  b+=section('Related services',cards(related))+cta()
  write('/'+group+'/'+slug+'/',title+' | California Counsel',desc,b)

