def redirect(file,target):
 dest=BASE+target
 p=ROOT/file;p.parent.mkdir(parents=True,exist_ok=True)
 p.write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Page Moved | RV Litigation Group PC</title><meta http-equiv="refresh" content="0; url={dest}"><link rel="canonical" href="{dest}"></head><body><p>This page has moved. <a href="{dest}">Continue to the current page</a>.</p></body></html>')
def migrations():
 old=json.loads((ROOT/'content/legacy-paths.json').read_text());active={str(path_for(u).relative_to(ROOT)) for u in PAGES}
 retired=[]
 for file in old:
  if file in active:continue
  if file in MOVED:
   redirect(file,MOVED[file])
   # GitHub Pages resolves /name to /name/ when a folder exists; both variants go direct to the final page.
   if file.endswith('/index.html'):
    redirect(file[:-11]+'.html',MOVED[file])
   else:redirect(file[:-5]+'/index.html',MOVED[file])
  else:
   (ROOT/file).unlink(missing_ok=True);retired.append('/'+file)
 (ROOT/'content/url-migration.json').write_text(json.dumps({'method':'zero-second HTML meta refresh; HTTP 200, not HTTP 301','keep_redirects_until_at_least':'2027-10-05','moved':MOVED,'retired':retired},indent=2)+'\n')
 urls=''.join(f'<url><loc>{BASE+u}</loc><lastmod>{DATE}</lastmod></url>' for u,p in PAGES.items() if p['index'])
 (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+urls+'</urlset>\n')
 (ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\n\nSitemap: https://rvlitigation.com/sitemap.xml\n')

